# -*- coding: utf-8 -*-
# (speaker, spanish, korean); speaker None => stage direction, "#" => scene heading (neither is a turn)
V, R, A, TE, X, L, RA = "Vicente", "Rosa", "Amparo", "Teresa", "Xavier", "Lucas", "Ramón"
D = [
("#", "Escena 1 · Sábado 20 de junio, 10:45 · Casa de Vicente, Onda", "장면 1 · 6월 20일 토요일 오전 10시 45분 · 온다, 비센테의 집"),
(None, "El comedor de los Albalat. La misma mesa larga de madera del domingo de la paella, ahora sin mantel: carpetas, botellas de agua y una jarra de horchata. En la pared, una foto en blanco y negro de 1958: un hombre joven delante de un horno de leña. Rosa coloca los vasos.", "알발라트 집안의 식당. 파에야를 먹던 일요일의 그 긴 나무 식탁에 이번엔 식탁보 대신 서류철과 물병, 오르차타 주전자가 놓였다. 벽에는 1958년 흑백 사진 한 장. 장작 가마 앞에 선 젊은 남자. 로사가 컵을 놓는다."),
(R, "Vicente, la horchata no la pongas al sol, que se corta.", "비센테, 오르차타 햇볕에 두지 마요. 상해요."),
(V, "Rosa, es una junta, no una merienda.", "로사, 주주총회지 간식 시간이 아니야."),
(R, "En esta casa las juntas siempre han acabado en merienda. Tu padre hacía las suyas con mistela.", "이 집에선 주주총회가 늘 간식으로 끝났어요. 당신 아버님은 미스텔라를 놓고 하셨죠."),
(None, "Suena el timbre. Entra Teresa Albalat, sesenta y ocho años, el pelo blanco recogido y un abanico en la mano. Detrás de ella, Xavier, cuarenta y cinco, americana azul y un sobre de Meridia bajo el brazo.", "초인종이 울린다. 예순여덟 살의 테레사 알발라트가 흰머리를 묶고 부채를 든 채 들어온다. 그 뒤로 마흔다섯 살의 하비에르가 남색 재킷 차림에 메리디아 봉투를 끼고 들어온다."),
(TE, "Vicente. (le da dos besos) Has adelgazado. ¿Duermes?", "비센테. (양 볼에 입을 맞추며) 살 빠졌네. 잠은 자?"),
(V, "Poco, Teresa. Como tú, imagino.", "조금, 누나. 누나도 그렇겠지."),
(X, "Buenos días, tío. Rosa. (mira a Lucas, que está junto a la ventana) Y usted debe de ser el famoso Lucas Ferrer.", "안녕하세요, 삼촌. 로사 숙모. (창가에 선 루카스를 보며) 그리고 당신이 그 유명한 루카스 페레르겠군요."),
(L, "Lucas, a secas. Encantado, Xavier.", "그냥 루카스요. 반갑습니다, 하비에르."),
(X, "Me han dicho que usted conoce a Borja Valcárcel. Que trabajaron juntos.", "보르하 발카르셀을 안다고 들었어요. 같이 일했다고."),
(L, "Seis años. Por eso hoy estoy aquí.", "6년이요. 그래서 오늘 여기 있는 거고요."),
(A, "(entra desde la cocina con un plato de almendras) Lucas está aquí porque se lo he pedido yo, Xavier. Y porque ha traído números que tú no tienes.", "(아몬드 접시를 들고 부엌에서 나오며) 루카스가 여기 있는 건 내가 부탁해서야, 하비에르. 그리고 네가 갖고 있지 않은 숫자를 가져왔으니까."),
(X, "Yo tengo los de Meridia. Cuarenta y dos millones. Me parecen bastante números.", "나는 메리디아 숫자가 있어. 4,200만. 그 정도면 충분한 숫자 같은데."),
(TE, "Niños, por favor. Todavía no hemos empezado y ya estáis como en la Nochebuena del noventa y cinco.", "얘들아, 제발. 아직 시작도 안 했는데 벌써 95년 크리스마스이브 꼴이구나."),
(R, "Siéntense. Ramón ya ha llegado y dice que a las once en punto empieza, que luego se pasa el arroz.", "앉으세요. 라몬이 벌써 왔는데 11시 정각에 시작한대요. 안 그러면 쌀이 퍼진다고."),

("#", "Escena 2 · 11:00 · La junta general", "장면 2 · 오전 11시 · 정기 주주총회"),
(RA, "Buenos días. Actúo como secretario de la junta, sin voto. Están presentes los cinco socios: Vicente, cuarenta por ciento; Rosa, diez; Amparo, quince; Teresa, veinte; Xavier, quince. Es decir, el cien por cien del capital. La junta queda válidamente constituida.", "안녕하십니까. 저는 의결권 없이 이번 총회의 서기를 맡습니다. 주주 다섯 분이 모두 출석하셨습니다. 비센테 40%, 로사 10%, 암파로 15%, 테레사 20%, 하비에르 15%. 즉 자본금의 100%입니다. 총회는 유효하게 성립되었습니다."),
(V, "Gracias, Ramón. Asisten también, sin voto, Lucas Ferrer, invitado por la mayoría de los socios.", "고마워, 라몬. 의결권 없이 루카스 페레르도 참석합니다. 과반 주주의 초청입니다."),
(X, "Que conste en acta que yo no lo he invitado.", "제가 초청하지 않았다는 건 회의록에 남겨 주세요."),
(RA, "Consta. Orden del día. Punto uno: autorizar o no la transmisión de participaciones a un tercero, Meridia Capital, según la oferta recibida el veinticinco de mayo. Punto dos: propuesta de nueva organización de la empresa. Punto tres: ruegos y preguntas.", "기록하겠습니다. 안건입니다. 첫째, 5월 25일 접수된 제안에 따라 제3자인 메리디아 캐피털에 대한 지분 양도를 승인할지 여부. 둘째, 회사의 새 조직안. 셋째, 기타 요청과 질의."),
(V, "Xavier, la oferta la has traído tú. Empieza tú.", "하비에르, 제안서는 네가 가져왔으니 네가 먼저 해라."),
(X, "Gracias, tío. Seré claro. Meridia valora la empresa en cuarenta y dos millones. Compraría primero nuestras participaciones, las mías y las de quien quiera vender, y después hasta el sesenta por ciento. A mi juicio, no vamos a ver otra oferta así en diez años.", "고마워요, 삼촌. 분명히 말할게요. 메리디아는 회사 가치를 4,200만으로 봅니다. 먼저 우리 지분, 그러니까 제 것과 팔고 싶은 사람 것을 사고, 그다음 60%까지 사려고 해요. 제 판단으로는, 10년 안에 이런 제안은 다시 안 옵니다."),
(A, "¿Y por qué no?", "왜 안 오는데?"),
(X, "Porque los fondos compran en lo alto. Y nosotros estamos en lo alto: Riad, Miami, México. ¿Y si el año que viene viene un arancel, se cae un cliente o se rompe un horno? Supongamos que todo sale mal. ¿Quién paga?", "펀드는 고점에서 사니까. 그리고 우린 지금 고점이야. 리야드, 마이애미, 멕시코. 내년에 관세가 생기거나, 고객 하나가 떨어지거나, 가마가 고장 나면? 다 잘못된다고 가정해 봐. 누가 책임져?"),
(TE, "Eso mismo me pregunto yo cada noche.", "나도 매일 밤 그걸 묻는다."),
(X, "Además, no solo traen dinero, sino también gente: directivos, sistemas, contactos en Asia. No es vender la casa. Es meter a alguien que sabe arreglarla.", "게다가 돈만 가져오는 게 아니라 사람도 데려와요. 임원, 시스템, 아시아 인맥. 집을 파는 게 아니라 집 고칠 줄 아는 사람을 들이는 거예요."),
(V, "¿Has terminado?", "다 했니?"),
(X, "Una cosa más. Yo vivo en Barcelona. No piso la fábrica desde hace años. Mis quince por ciento son, para mí, un número en un papel. Prefiero un número en una cuenta.", "하나만 더요. 저는 바르셀로나에 살아요. 공장에 발도 안 디딘 지 몇 년 됐어요. 제 15%는 저한테 종이 위의 숫자예요. 저는 통장 속 숫자가 좋아요."),
(TE, "Xavier tiene razón en una cosa: yo tampoco piso la fábrica. Pero la veo cada vez que paso por la carretera de Onda, la chimenea echando humo.", "하비에르 말이 하나는 맞아. 나도 공장에 발을 안 디뎌. 하지만 온다 도로를 지날 때마다 보이지. 연기 나는 굴뚝이."),
(A, "Tía, esa chimenea echa humo gracias a los contratos de este año. Hace dieciocho meses teníamos un horno parado y treinta y dos personas en ERTE.", "고모, 그 굴뚝은 올해 계약 덕분에 연기를 뿜는 거예요. 18개월 전엔 가마 하나가 서 있었고 서른두 명이 일시 휴직 중이었어요."),
(X, "Y hace dos años Meridia ofrecía la mitad. Eso también ha cambiado.", "그리고 2년 전엔 메리디아가 절반을 불렀지. 그것도 바뀌었고."),
(V, "Por eso les dijimos que no entonces. Y por eso nos buscan ahora.", "그래서 그때 우리가 거절했던 거다. 그리고 그래서 지금 우리를 찾는 거고."),
(RA, "Tiene la palabra el señor Ferrer, a petición de Amparo.", "암파로의 요청으로 페레르 씨에게 발언권을 드립니다."),
(L, "Gracias. Voy a hablar de números, como Xavier. Pero de los dos lados del papel.", "감사합니다. 하비에르처럼 숫자 얘기를 하겠습니다. 하지만 종이의 양면 모두요."),
(X, "Adelante.", "해 보세요."),
(L, "Primer número: cuarenta y dos millones es el valor de hoy. Con lo firmado en Riad, Miami, Texas, Bogotá y, si sale, Seúl, Ramón calcula que en dos años facturaremos unos ochenta y cinco millones, con un EBITDA de ocho y medio.", "첫째 숫자. 4,200만은 오늘의 가치입니다. 리야드, 마이애미, 텍사스, 보고타, 그리고 성사되면 서울까지 서명한 것을 합치면, 라몬 계산으로 2년 뒤 매출은 약 8,500만, 상각 전 영업이익은 850만입니다."),
(RA, "Con los contratos firmados, no con promesas. Lo he revisado tres veces.", "약속이 아니라 서명된 계약 기준입니다. 세 번 검토했습니다."),
(L, "Es decir: si vendemos hoy, vendemos barato lo que en dos años valdrá bastante más. Lejos de comprar en lo alto, Meridia compra antes de que se vea lo alto.", "다시 말해, 오늘 팔면 2년 뒤 훨씬 더 가치 있을 것을 싸게 파는 겁니다. 메리디아는 고점에 사기는커녕, 고점이 보이기 전에 사는 거예요."),
(X, "Eso es una proyección. Las proyecciones las hace cualquiera.", "그건 전망이죠. 전망은 누구나 만들어요."),
(L, "Tiene razón. Yo hacía proyecciones para Borja. Por eso le enseño la otra cara. (abre una carpeta) Este es el plan que Meridia aplicó en l'Alcora. Lo escribí yo, hace tres años.", "맞습니다. 저도 보르하를 위해 전망을 만들었죠. 그래서 반대쪽을 보여 드리는 겁니다. (서류철을 펼치며) 이게 메리디아가 라르코라에서 쓴 계획입니다. 3년 전에 제가 썼습니다."),
(TE, "¿Usted?", "당신이?"),
(L, "Yo, señora. Página doce: «racionalización». Cerraron la fábrica en seis meses. Ciento ochenta personas. Y hoy la marca de l'Alcora se fabrica en Turquía, con el nombre del pueblo en la caja.", "네, 제가요. 12쪽, '합리화'. 6개월 만에 공장을 닫았습니다. 180명이었죠. 그리고 지금 라르코라 브랜드는 튀르키예에서 만들어져요. 상자에 마을 이름을 붙여서."),
(X, "Albalat no es l'Alcora.", "알발라트는 라르코라가 아니에요."),
(L, "No. Pero el plan que me enseñó Borja en mayo empieza por el horno dos. Ochenta y siete personas. Externalizar a Portugal o a Turquía.", "아니죠. 하지만 5월에 보르하가 보여 준 계획은 2호기부터 시작합니다. 여든일곱 명. 포르투갈이나 튀르키예로 외주화."),
(R, "(muy bajo) El horno dos lo encendió el padre de Vicente en el setenta y uno.", "(아주 작게) 2호기는 비센테 아버님이 71년에 불을 붙이셨어요."),
(A, "Y hoy lo maneja la hija de Encarna. Y el hijo de Juanjo entra en septiembre como aprendiz.", "그리고 지금은 엔카르나 딸이 그걸 돌려요. 후안호 아들은 9월에 견습공으로 들어오고요."),
(X, "Esto es lo que yo llamo sentimentalismo, prima.", "이게 내가 말하는 감상주의야, 사촌."),
(L, "No es sentimentalismo, Xavier. Es riesgo. Si cerramos el dos, perdemos el mercado nacional, que todavía es el sesenta y cinco por ciento de lo que vendemos. Y perdemos a la gente que ha hecho posible lo de Riad.", "감상이 아니에요, 하비에르. 리스크예요. 2호기를 닫으면 국내 시장을 잃어요. 아직도 우리 매출의 65%예요. 그리고 리야드를 가능하게 한 사람들을 잃고요."),
(X, "¿Y Asia? Solos no pueden abrir Seúl. Meridia tiene oficina en Singapur.", "아시아는요? 혼자선 서울 못 열어요. 메리디아는 싱가포르에 사무소가 있어요."),
(L, "Seúl lo está abriendo una señora que estudió en Salamanca y que llamó a Pepe para preguntarle por las cajas. No necesita una oficina en Singapur. Necesita que las cajas lleguen sin polvo.", "서울은 살라망카에서 공부한 한 대표가 열어 주고 있어요. 상자 얘기로 페페한테 전화까지 한 분이죠. 싱가포르 사무소는 필요 없어요. 상자가 먼지 없이 도착하면 돼요."),
(TE, "¿Y llegan sin polvo?", "그래서 먼지 없이 도착해요?"),
(L, "Desde que Paco puso un extractor encima de la línea, sí. La señora Kim dice que es la primera caja europea que abre limpia.", "파코가 라인 위에 환풍기를 단 뒤로는요. 김 대표 말로는 깨끗하게 열린 유럽 상자는 처음이래요."),
(X, "Anécdotas.", "일화일 뿐이죠."),
(RA, "Pedidos, Xavier. Noventa mil metros en dos años, si firman. No es una anécdota: es un tercio del horno uno.", "주문이에요, 하비에르. 서명하면 2년간 9만㎡. 일화가 아니라 1호기의 3분의 1이에요."),
(TE, "Ramón, tú que no votas: ¿tú qué harías?", "라몬, 당신은 투표권이 없잖아요. 당신이라면 어떻게 하겠어요?"),
(RA, "A mi juicio, yo hoy no vendería. Pero yo no tengo dos hijos en la universidad, Teresa.", "제 판단으로는 오늘은 안 팔겠습니다. 하지만 저는 대학생 아이가 둘 있는 사람이 아니에요, 테레사."),
(TE, "No. No los tienes.", "그래요. 당신은 아니죠."),
(V, "(golpea suavemente la mesa) Bien. Creo que todos hemos oído lo suficiente. Ramón, sometemos el punto uno a votación.", "(식탁을 가볍게 두드리며) 좋아. 다들 충분히 들은 것 같다. 라몬, 첫 번째 안건을 표결에 부치자."),
(RA, "Punto uno: ¿autoriza la junta la transmisión de participaciones a Meridia Capital? Votos a favor.", "첫 번째 안건. 총회는 메리디아 캐피털에 대한 지분 양도를 승인합니까? 찬성하시는 분."),
(X, "A favor. Quince.", "찬성. 15."),
(RA, "¿Teresa?", "테레사 씨?"),
(None, "Teresa cierra el abanico. Mira la foto de 1958. Tarda en hablar.", "테레사가 부채를 접는다. 1958년 사진을 바라본다. 한참 동안 말이 없다."),
(TE, "A favor. Veinte. Y que conste en acta por qué: voto a favor porque necesito el dinero, no porque quiera venderla. Tengo dos hijos en la universidad y una casa en Valencia que se cae a trozos.", "찬성. 20. 그리고 이유도 회의록에 남겨 줘요. 돈이 필요해서 찬성하는 거지, 팔고 싶어서가 아니에요. 대학생 아이가 둘이고, 발렌시아 집은 무너져 가요."),
(RA, "Consta. Votos en contra.", "기록했습니다. 반대하시는 분."),
(V, "En contra. Cuarenta.", "반대. 40."),
(R, "En contra. Diez.", "반대. 10."),
(A, "En contra. Quince.", "반대. 15."),
(RA, "Resultado: treinta y cinco por ciento a favor, sesenta y cinco en contra. El punto uno queda rechazado por mayoría.", "결과. 찬성 35%, 반대 65%. 첫 번째 안건은 다수결로 부결되었습니다."),
(X, "(se recuesta en la silla) Era de esperar. Pero entonces, tío, ¿qué hacemos los que queremos salir? ¿Nos quedamos presos de un número en un papel?", "(의자에 등을 기대며) 예상했던 일이죠. 그럼 삼촌, 나가고 싶은 사람은 어떻게 해요? 종이 위 숫자에 갇혀 있으라고요?"),
(V, "No. Para eso está el punto dos. Amparo.", "아니. 그래서 두 번째 안건이 있는 거다. 암파로."),
(A, "Punto dos. Proponemos tres cosas. Una: papá deja la dirección y pasa a ser presidente de honor. Yo asumo como consejera delegada.", "두 번째 안건. 세 가지를 제안합니다. 하나, 아빠는 경영에서 물러나 명예회장이 됩니다. 제가 대표이사를 맡습니다."),
(TE, "Ya era hora, hija. Tu abuelo lo habría querido así.", "때가 됐지, 얘야. 네 할아버지도 그걸 원하셨을 거야."),
(A, "Dos: Lucas, como director general. Con una ampliación de capital reservada para él: un cinco por ciento, a valor de mercado, que pagará con su propio dinero. Con un préstamo personal, no con el nuestro.", "둘, 루카스를 총괄 사장으로. 그를 위한 증자도 함께요. 5%를 시장 가치로, 본인 돈으로 납입합니다. 우리 돈이 아니라 개인 대출로요."),
(X, "¿Le damos acciones a alguien de fuera? Lo que no quería el abuelo era precisamente eso.", "외부 사람한테 지분을 준다고? 할아버지가 바로 그걸 싫어하셨잖아."),
(V, "Lo que no quería tu abuelo era que la casa la decidieran desde un despacho de Madrid. Lucas decide desde aquí. Y lleva dieciséis meses demostrándolo.", "네 할아버지가 싫어하신 건 마드리드 사무실에서 이 집안 일을 결정하는 거였다. 루카스는 여기서 결정해. 그리고 16개월 동안 그걸 증명해 왔고."),
(A, "Y tres, que es para vosotros. Quien quiera vender podrá hacerlo, pero a la familia, a valor de mercado y poco a poco: papá y mamá ejercerán su derecho de adquisición preferente, a razón de un cuatro por ciento al año como máximo.", "그리고 셋, 이건 두 분을 위한 거예요. 팔고 싶은 사람은 팔 수 있어요. 다만 가족에게, 시장 가치로, 조금씩. 아빠와 엄마가 우선 매수권을 행사합니다. 1년에 최대 4%까지."),
(TE, "¿A valor de mercado? ¿Quién lo fija?", "시장 가치로? 그건 누가 정해?"),
(RA, "Un experto independiente, cada año. Si Lucas tiene razón, dentro de dos años ese valor será más alto que el de Meridia.", "독립 전문가가 매년 정합니다. 루카스 말이 맞다면, 2년 뒤 그 가치는 메리디아 평가보다 높을 겁니다."),
(TE, "Supongamos que no la tiene.", "그 말이 틀렸다고 가정해 봐요."),
(L, "Entonces, señora, le habré costado dinero. Y usted podrá recordármelo cada Navidad.", "그러면, 부인, 제가 돈을 손해 보게 해 드린 거겠죠. 그리고 매년 크리스마스마다 저한테 그 얘길 하셔도 됩니다."),
(TE, "(casi sonríe) Tiene usted cara de que se lo recordaría.", "(웃을 뻔하며) 내가 정말 그럴 것 같은 얼굴이네."),
(X, "¿Y yo? ¿Un cuatro por ciento al año? En cuatro años tengo mi dinero. Con Meridia lo tenía en un mes.", "저는요? 1년에 4%? 4년이면 돈이 다 들어오겠네요. 메리디아면 한 달이었는데."),
(R, "Con Meridia lo tenías en un mes, sí. Y la abuela Pilar no te habría vuelto a invitar a comer en su vida.", "메리디아면 한 달이었겠지, 그래. 그리고 필라르 할머니는 평생 다시는 너를 점심에 안 부르셨을 거야."),
(None, "Por primera vez en toda la mañana, Xavier se ríe. Una risa corta, a su pesar.", "아침 내내 처음으로 하비에르가 웃는다. 짧고, 마지못한 웃음이다."),
(X, "La abuela Pilar está en Benicàssim y tiene noventa y un años.", "필라르 할머니는 베니카심에 계시고 아흔한 살이에요."),
(R, "Y la memoria de una niña de quince.", "그리고 열다섯 살 아이의 기억력이 있으시지."),
(V, "Ramón, punto dos a votación.", "라몬, 두 번째 안건 표결."),
(RA, "Punto dos: nueva organización, ampliación de capital y régimen de venta a la familia, en los términos expuestos. Votos a favor.", "두 번째 안건. 제시된 조건에 따른 새 조직, 증자, 가족 대상 매각 규정. 찬성하시는 분."),
(V, "A favor.", "찬성."),
(R, "A favor.", "찬성."),
(A, "A favor.", "찬성."),
(TE, "A favor. Esta vez sí, porque quiero.", "찬성. 이번엔 정말 원해서요."),
(X, "(un silencio) Me abstengo. Que conste que no me opongo. Pero tampoco os voy a aplaudir.", "(침묵) 기권합니다. 반대하지 않는다는 건 기록해 주세요. 그렇다고 박수를 치진 않을 거예요."),
(RA, "Consta. Ochenta y cinco por ciento a favor, quince por ciento de abstención. El punto dos queda aprobado. Con una condición que figura en la propuesta: que el señor Ferrer acepte el cargo.", "기록했습니다. 찬성 85%, 기권 15%. 두 번째 안건은 승인되었습니다. 다만 제안서에 적힌 조건이 하나 있습니다. 페레르 씨가 직책을 수락해야 한다는 것."),
(None, "Todos se vuelven hacia Lucas.", "모두가 루카스 쪽으로 몸을 돌린다."),
(L, "Les pido una cosa. Cuarenta y ocho horas. No para pensar en el dinero. Para cerrar bien una puerta en Madrid antes de abrir esta.", "하나만 부탁드립니다. 48시간이요. 돈 생각을 하려는 게 아닙니다. 이 문을 열기 전에 마드리드의 문을 제대로 닫으려고요."),
(A, "Cuarenta y ocho horas. Ni una más.", "48시간. 단 한 시간도 더는 안 돼요."),
(L, "Ni una servilleta más.", "냅킨 한 장도 더는 안 되죠."),
(RA, "Punto tres: ruegos y preguntas.", "세 번째 안건. 기타 요청과 질의."),
(R, "Un ruego: que nos levantemos, que el arroz al horno lleva diez minutos fuera y se está secando.", "요청 하나. 일어납시다. 오븐 쌀 요리가 나온 지 10분이 지나서 말라 가요."),
(RA, "Consta. Se levanta la sesión a las doce y cuarenta.", "기록하겠습니다. 12시 40분에 폐회합니다."),

("#", "Escena 3 · 14:30 · La sobremesa", "장면 3 · 오후 2시 30분 · 식후 담소"),
(None, "Arroz al horno, una ensalada de tomate de Burriana y, al final, la mistela del abuelo. Xavier se ha quitado la americana. Teresa abanica a Rosa. Lucas y Vicente salen al pequeño patio, donde hay un limonero.", "오븐 쌀 요리, 부리아나 토마토 샐러드, 그리고 마지막으로 할아버지의 미스텔라. 하비에르는 재킷을 벗었다. 테레사가 로사에게 부채질을 해 준다. 루카스와 비센테는 레몬 나무가 있는 작은 안뜰로 나간다."),
(V, "Has dicho «cerrar una puerta en Madrid». ¿Es la de Borja o es otra?", "'마드리드의 문을 닫는다'고 했지. 보르하의 문이야, 다른 문이야?"),
(L, "Las dos. La de Borja se cierra con una llamada. La otra es la del Lucas que hacía Excels. Esa cuesta más.", "둘 다요. 보르하의 문은 전화 한 통이면 닫혀요. 다른 하나는 엑셀을 만들던 루카스의 문이에요. 그게 더 어려워요."),
(V, "(arranca una hoja del limonero y la huele) Yo tardé tres semanas en dormir después de Meridia. ¿Lo sabías?", "(레몬 잎 하나를 따서 냄새를 맡으며) 메리디아 다음에 나는 3주 동안 잠을 못 잤어. 알고 있었어?"),
(L, "Me lo contó Amparo. En Monterrey.", "암파로가 말해 줬어요. 몬테레이에서요."),
(V, "Esta noche voy a dormir. Pase lo que pase con tu respuesta. ¿Y sabes por qué?", "오늘 밤엔 잘 거야. 자네 대답이 어떻든. 왜인지 알아?"),
(L, "¿Por la votación?", "표결 때문에요?"),
(V, "No. Porque hoy, por primera vez, no he tenido que defender la casa solo.", "아니. 오늘 처음으로 이 집을 혼자 지키지 않아도 됐으니까."),
(L, "Nunca la ha defendido solo, Vicente. Tenía toda la fábrica detrás.", "혼자 지키신 적 없어요, 비센테. 공장 전체가 뒤에 있었잖아요."),
(V, "Detrás, sí. Hoy alguien se ha puesto delante. Es distinto.", "뒤에는 있었지. 오늘은 누군가 앞에 섰어. 그건 달라."),
(L, "Amparo se ha puesto delante.", "암파로가 앞에 섰죠."),
(V, "Los dos. Y Teresa, a su manera. ¿La has visto? Ha votado a favor de vender y luego a favor de quedarse. Así es mi hermana: honesta incluso cuando se contradice.", "둘 다. 그리고 테레사도 자기 방식으로. 봤어? 팔자는 데 찬성하고, 그다음엔 남자는 데 찬성했어. 우리 누나는 그래. 모순될 때조차 정직해."),
(L, "Me ha caído bien.", "마음에 드는 분이에요."),
(V, "Pues prepárate: cada Navidad te preguntará por las proyecciones.", "그럼 각오해. 크리스마스마다 전망 얘기를 물을 거야."),
(X, "(asoma por la puerta del patio, con un vaso de mistela) Lucas, ¿un minuto?", "(미스텔라 잔을 들고 안뜰 문으로 고개를 내밀며) 루카스, 잠깐 시간 돼요?"),
(L, "Claro.", "물론이죠."),
(X, "No pienso que tenga razón. Pero ha hablado claro. Y ha dicho lo de l'Alcora delante de todos, cuando le habría convenido callárselo.", "당신이 옳다고 생각하진 않아요. 하지만 분명하게 말했어요. 그리고 숨기는 게 유리했을 텐데 라르코라 얘기를 모두 앞에서 했죠."),
(L, "Me lo aconsejó alguien: decir lo que pienso, no lo que conviene.", "누가 그렇게 조언했어요. 유리한 말 말고 생각하는 걸 말하라고."),
(X, "¿Pepe?", "페페?"),
(L, "Pepe.", "페페요."),
(X, "(levanta el vaso) Pues brindo por las proyecciones. Dentro de dos años vengo a ver si ochenta y cinco son ochenta y cinco.", "(잔을 들며) 그럼 전망을 위해 건배하죠. 2년 뒤에 8,500만이 진짜 8,500만인지 보러 올게요."),
(V, "Y te quedas a comer.", "그리고 점심 먹고 가."),
(X, "Si hay arroz al horno, sí.", "오븐 쌀 요리가 있다면요."),
(L, "Lo habrá. Aunque sea en Seúl.", "있을 거예요. 서울에서라도."),
(A, "(desde dentro) ¡Lucas! Mi madre dice que, si no entras a por el postre, se lo da a Marc.", "(안에서) 루카스! 엄마가 디저트 먹으러 안 들어오면 마르크한테 준대요!"),
(L, "¡Voy!", "가요!"),
(None, "Antes de entrar, Lucas mira la foto de 1958 a través de la ventana del comedor. Saca el móvil. En la pantalla, el número de Borja Valcárcel. No llama todavía. Guarda el móvil y entra.", "들어가기 전에 루카스가 식당 창문 너머로 1958년 사진을 본다. 휴대폰을 꺼낸다. 화면에 보르하 발카르셀의 번호. 아직 전화하지 않는다. 휴대폰을 넣고 안으로 들어간다."),
]

